export interface RateLimitOptions {
  windowMs: number;
  max: number;
}

export interface RateLimitDecision {
  allowed: boolean;
  remaining: number;
  resetAt: number;
}

export function createFixedWindowLimiter(options: RateLimitOptions) {
  if (!Number.isInteger(options.max) || options.max < 1) throw new RangeError('max must be a positive integer');
  if (!Number.isFinite(options.windowMs) || options.windowMs <= 0) throw new RangeError('windowMs must be positive');
  const buckets = new Map<string, { count: number; resetAt: number }>();

  return function check(key: string, now = Date.now()): RateLimitDecision {
    const current = buckets.get(key);
    const bucket = !current || now >= current.resetAt
      ? { count: 0, resetAt: now + options.windowMs }
      : current;
    bucket.count += 1;
    buckets.set(key, bucket);
    return {
      allowed: bucket.count <= options.max,
      remaining: Math.max(0, options.max - bucket.count),
      resetAt: bucket.resetAt,
    };
  };
}

import { strict as assert } from 'node:assert';
import { createFixedWindowLimiter } from '../src/rate-limit.js';

const check = createFixedWindowLimiter({ windowMs: 1000, max: 2 });
assert.deepEqual(check('ada', 100), { allowed: true, remaining: 1, resetAt: 1100 });
assert.deepEqual(check('ada', 200), { allowed: true, remaining: 0, resetAt: 1100 });
assert.deepEqual(check('ada', 300), { allowed: false, remaining: 0, resetAt: 1100 });
assert.deepEqual(check('ada', 1100), { allowed: true, remaining: 1, resetAt: 2100 });
